changeSet.sql:
CREATE TABLE IF NOT EXISTS customer (
    id BIGSERIAL PRIMARY KEY,
    first_name VARCHAR(255) NOT NULL,
    last_name VARCHAR(255) NOT NULL,
    age INT,
    payment NUMERIC(19, 2)
    );
CREATE INDEX IF NOT EXISTS idx_customer_last_name ON customer(last_name);
CREATE INDEX IF NOT EXISTS idx_customer_age ON customer(age);
CREATE INDEX IF NOT EXISTS idx_customer_last_name_age ON customer(last_name, age);
